SELECT id, record_time recordTime, `type`, department, `name`, identify_mode identifyMode, key_no keyNo
FROM key_cabinet_log


        `type` = #{type}


        AND key_no = #{keyNo}


        AND `name` LIKE CONCAT(#{name}, '%')


        AND record_time >= #{startTime}


        AND record_time <= #{endTime}


ORDER BY create_time DESC

    limit #{page}, #{row}

SELECT COUNT(*) count
FROM key_cabinet_log


        `type` = #{type}


        AND key_no = #{keyNo}


        AND `name` LIKE CONCAT(#{name}, '%')


        AND record_time >= #{startTime}


        AND record_time <= #{endTime}
